(1638274, 221243, 670, '<td valign="top">Good for you!  Good use of framing.</td>', 'Good for you!  Good use of framing.', '2005-08-24 02:58:43.000000', NULL, 1),
(1638277, 220374, 670, '<td valign="top">I like the use of shadows and the red tie helps add just the right touch of color.</td>', 'I like the use of shadows and the red tie helps add just the right touch of color.', '2005-08-24 02:59:41.000000', NULL, 1),
