INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1650096, 220982, 15810, '<td valign="top">Beautifully simple. Superb lighting &amp; exposure and great focus. I really like this...less is more as they say.</td>', 'Beautifully simple. Superb lighting & exposure and great focus. I really like this...less is more as they say.', '2005-08-27 17:02:42.000000', NULL, 1),
(1650098, 221256, 15810, '<td valign="top">Cant stop looking at the shadows, blobs? in the white negative space of the image.</td>', 'Cant stop looking at the shadows, blobs? in the white negative space of the image.', '2005-08-27 17:03:59.000000', NULL, 1),
(1650102, 220286, 15810, '<td valign="top">Interesting, but not sure if this would stand up as an interesting image outside this challenge. Wel done and for submitting to this difficult challenge anyway.</td>', 'Interesting, but not sure if this would stand up as an interesting image outside this challenge. Wel done and for submitting to this difficult challenge anyway.', '2005-08-27 17:05:46.000000', NULL, 1),
(1650103, 220472, 10634, '<td valign="top">Good perspective.... focus is too soft on her face, though. If her face were sharp, you would be drawn through the photo and along her body. Right now, the focus is her chest and you are just kind of thrown there.</td>', 'Good perspective.... focus is too soft on her face, though. If her face were sharp, you would be drawn through the photo and along her body. Right now, the focus is her chest and you are just kind of thrown there.', '2005-08-27 17:06:10.000000', NULL, 1),
(1650104, 221248, 15810, '<td valign="top">Soft lighting, soft focus, soft material but ultimately just not enough to make this an interesting image.</td>', 'Soft lighting, soft focus, soft material but ultimately just not enough to make this an interesting image.', '2005-08-27 17:06:32.000000', NULL, 1),
(1650108, 221013, 15810, '<td valign="top">This is one of the most stunning images of the last 12 months of challenges, If you dont post how this was done afterwards your obvious forthcoming ribbon should be taken away from you and your membership revoked. 10</td>', 'This is one of the most stunning images of the last 12 months of challenges, If you dont post how this was done afterwards your obvious forthcoming ribbon should be taken away from you and your membership revoked. 10', '2005-08-27 17:08:28.000000', NULL, 1),
(1650110, 221083, 15810, '<td valign="top">Lovethe blurry image withthe wet look, hints at a steamy location. Nicely done.</td>', 'Lovethe blurry image withthe wet look, hints at a steamy location. Nicely done.', '2005-08-27 17:09:19.000000', NULL, 1),
(1650112, 219696, 15810, '<td valign="top">Beautifully exposed and lovely colours and composition.</td>', 'Beautifully exposed and lovely colours and composition.', '2005-08-27 17:10:06.000000', NULL, 1),
