(1650591, 221087, 33552, '<td valign="top">LOL. Cute. Don''t know if a tux is considered nude though. Anyway, nice tone, lighting, and concept.</td>', 'LOL. Cute. Don''t know if a tux is considered nude though. Anyway, nice tone, lighting, and concept.', '2005-08-27 21:18:52.000000', NULL, 1),
(1650594, 220166, 33552, '<td valign="top">Well done. Use of the suit as a focal point makes this shot work.</td>', 'Well done. Use of the suit as a focal point makes this shot work.', '2005-08-27 21:20:12.000000', NULL, 1),
(1650598, 220656, 33552, '<td valign="top">Great use of foreground. Well executed.</td>', 'Great use of foreground. Well executed.', '2005-08-27 21:23:10.000000', NULL, 1),
(1650600, 220472, 30625, '<td valign="top">Very unique take on the subject but I wish you would have started the focus point on her face and worked down. The result would have been better (9)</td>', 'Very unique take on the subject but I wish you would have started the focus point on her face and worked down. The result would have been better (9)', '2005-08-27 21:23:34.000000', NULL, 1),
(1650602, 219720, 30625, '<td valign="top">I had to zoom in on the spout I thought that it was the drain and you were you know "dribbling" into it.</td>', 'I had to zoom in on the spout I thought that it was the drain and you were you know "dribbling" into it.', '2005-08-27 21:24:41.000000', NULL, 1),
